from __future__ import annotations
import warnings
warnings.filterwarnings("ignore")
import os
from datetime import datetime
from pathlib import Path
from typing import Any

from dotenv import load_dotenv
from langchain_core.prompts import ChatPromptTemplate
from langchain_openai import ChatOpenAI

# %%
OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1"
LLM_MODEL = "openai/gpt-5.4-mini"  # latest small OpenAI model, fast; covered by course credits
TEMPERATURE = 0.2
LOG_PATH = Path.cwd() / "checkpoint_1_1_output.log"

# === SET THIS to your chosen scenario ===
SCENARIO = "wikipedia"   # "research_papers" or "wikipedia"

SYSTEM_PROMPT = (
    "You are a helpful research assistant. Answer the user's question as "
    "accurately as you can. When you reference a specific document, quote "
    "from it directly. If you are not certain, say so rather than guessing."
)

# %%
def check_api_key() -> str:
    load_dotenv()
    key = os.getenv("OPENROUTER_API_KEY")
    if not key:
        raise RuntimeError(
            "OPENROUTER_API_KEY not set. Grab a free key at "
            "https://openrouter.ai/keys, put it in a .env file next to this "
            "script, and rerun."
        )
    return key


def build_chain() -> Any:
    """Baseline LLM chain — no retrieval. Same pattern as Lab 1.1."""
    llm = ChatOpenAI(
        model=LLM_MODEL,
        temperature=TEMPERATURE,
        api_key=check_api_key(),
        base_url=OPENROUTER_BASE_URL,
    )
    prompt = ChatPromptTemplate.from_messages([
        ("system", SYSTEM_PROMPT),
        ("human", "{question}"),
    ])
    return prompt | llm


def ask(chain: Any, question: str) -> str:
    resp = chain.invoke({"question": question})
    return resp.content if hasattr(resp, "content") else str(resp)


def log_response(scenario: str, prompt: str, response: str) -> None:
    ts = datetime.now().isoformat(timespec="seconds")
    entry = (
        f"[{ts}]  SCENARIO={scenario}  MODEL={LLM_MODEL}\n"
        f"PROMPT:   {prompt}\n"
        f"RESPONSE: {response}\n"
        f"{'-' * 72}\n"
    )
    with LOG_PATH.open("a", encoding="utf-8") as fh:
        fh.write(entry)

