# %% [markdown]
# ## Step 4 — Run the baseline probes and capture the evidence
#
# This runs the example prompts plus your own through the **no-retrieval** LLM and logs every prompt/response to `checkpoint_1_1_responses.log`. Read each answer against the real document (open it in the dataset folder) and classify what you see: hallucination, hedge, generic-but-unsourced, or correct.

# %%
def run_probes() -> None:
    check_api_key()
    chain = build_chain()
    prompts = my_probe_prompts() # Run ONLY your Step 3 probe prompts
    
    print(f"Capstone Checkpoint 1.1 — baseline (no retrieval)")
    print(f"Scenario: {SCENARIO}  |  Model: {LLM_MODEL}")
    print(f"\nRunning {len(prompts)} probe prompts...\n")
    print(f"Logging to: {LOG_PATH.name}\n")
    print("-" * 72)
    
    for i, question in enumerate(prompts, start=1):
        print(f"\nPROMPT {i}/{len(prompts)}:")
        print(question)
        response = ask(chain, question)
        print("\nRESPONSE:")
        print(response)
        print("-" * 72)
        log_response(SCENARIO, question, response)
    print("Done. Now READ each response against the real document. For each, "
    "note: did the model hallucinate, hedge, give a generic unsourced "
    "answer, or get it right? This is the evidence for your write-up.")

run_probes()
